import * as THREE from 'three/webgpu';
import { texture, uv, vec4, mix, float, uniform } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-card-1-label';
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height);

  const map = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const uvNode = uv();
  const baseTex = texture(map, uvNode);

  const inkColor = uniform(new THREE.Color('#16161d'));
  const surfaceColor = uniform(new THREE.Color('#0b0b10'));

  const gradientMix = uvNode.y.clamp(0.0, 1.0);
  const gradient = mix(vec4(surfaceColor, 1.0), vec4(inkColor, 1.0), gradientMix);

  const combined = mix(gradient, baseTex, float(0.35));

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = combined;
  material.transparent = false;

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'hub-journal-card-1-label-plane';
  group.add(plane);

  const textMeshes = [];
  const textContent = Array.isArray(config.textContent) ? config.textContent : [];

  for (const entry of textContent) {
    const mesh = createTextMesh({
      text: entry.text,
      font: entry.role === 'headline' ? 'Lora' : 'JetBrains Mono',
      weight: entry.weight || 400,
      size: entry.role === 'headline' ? 0.34 : 0.13,
      color: '#e8ecf2',
      atlas: ctx.fontAtlas,
      align: 'center',
      anchor: 'center'
    });
    mesh.position.set(0, 0, 0.01);
    mesh.name = `hub-journal-card-1-label-text-${entry.role || 'text'}`;
    group.add(mesh);
    textMeshes.push(mesh);
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    for (const mesh of textMeshes) {
      if (mesh.geometry) mesh.geometry.dispose();
      if (mesh.material) mesh.material.dispose();
    }
  };

  return group;
}
